'use strict';
// Order 資料模型：欄位定義與驗證
/**
 * @typedef {Object} Order
 * @property {string} id
 * @property {string} customerId
 * @property {string} productId
 * @property {number} quantity
 */

const FIELDS = ["customerId","productId","quantity"];

/** @returns {string[]} 錯誤訊息，空陣列代表合法 */
function validateOrder(input) {
  const errors = [];
  if (input === null || typeof input !== 'object') return ['輸入必須是物件'];
  if (input.customerId === undefined) errors.push('customerId 為必填');
  if (input.customerId !== undefined && typeof input.customerId !== 'string') errors.push('customerId 必須是 string');
  if (input.productId === undefined) errors.push('productId 為必填');
  if (input.productId !== undefined && typeof input.productId !== 'string') errors.push('productId 必須是 string');
  if (input.quantity === undefined) errors.push('quantity 為必填');
  if (input.quantity !== undefined && typeof input.quantity !== 'number') errors.push('quantity 必須是 number');
  return errors;
}

/** @returns {Order} */
function buildOrder(id, input) {
  return {
    id,
    customerId: input.customerId,
    productId: input.productId,
    quantity: input.quantity,
  };
}

module.exports = { FIELDS, validateOrder, buildOrder };
'use strict';
// Order 服務層：記憶體儲存的 CRUD
const { validateOrder, buildOrder } = require('../models/order');
const { createStore } = require('../lib/store');
const { ValidationError, NotFoundError } = require('../lib/errors');

function createOrderService(store = createStore('order')) {
  return {
    create(input) {
      const errors = validateOrder(input);
      if (errors.length) throw new ValidationError(errors);
      return store.insert((id) => buildOrder(id, input));
    },
    get(id) {
      const item = store.find(id);
      if (!item) throw new NotFoundError('order', id);
      return item;
    },
    list() {
      return store.all();
    },
    update(id, patch) {
      const current = this.get(id);
      const merged = { ...current, ...patch };
      const errors = validateOrder(merged);
      if (errors.length) throw new ValidationError(errors);
      return store.replace(id, buildOrder(id, merged));
    },
    remove(id) {
      this.get(id);
      store.delete(id);
      return true;
    },
  };
}

module.exports = { createOrderService };
'use strict';
// Order 路由：把 {method, params, body} 轉成服務呼叫並回傳 {status, body}
const { createOrderService } = require('../services/order');
const { toResponse } = require('../lib/http');

function orderRoutes(service = createOrderService()) {
  return {
    'GET /orders': () => toResponse(() => ({ status: 200, body: service.list() })),
    'GET /orders/:id': (req) => toResponse(() => ({ status: 200, body: service.get(req.params.id) })),
    'POST /orders': (req) => toResponse(() => ({ status: 201, body: service.create(req.body) })),
    'PUT /orders/:id': (req) => toResponse(() => ({ status: 200, body: service.update(req.params.id, req.body) })),
    'DELETE /orders/:id': (req) => toResponse(() => { service.remove(req.params.id); return { status: 204, body: null }; }),
  };
}

module.exports = { orderRoutes };
'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { validateOrder } = require('../src/models/order');
const { createOrderService } = require('../src/services/order');
const { orderRoutes } = require('../src/routes/order');

const VALID = { customerId: 'sample-0', productId: 'sample-1', quantity: 3 };

test('order model：合法輸入沒有錯誤', () => {
  assert.deepEqual(validateOrder(VALID), []);
});

test('order model：缺必填欄位 customerId', () => {
  const { customerId: _omit, ...rest } = VALID;
  assert.ok(validateOrder(rest).length > 0);
});

test('order service：create/get/update/remove', () => {
  const svc = createOrderService();
  const created = svc.create(VALID);
  assert.equal(svc.get(created.id).id, created.id);
  assert.equal(svc.list().length, 1);
  svc.update(created.id, {});
  assert.equal(svc.remove(created.id), true);
  assert.throws(() => svc.get(created.id), /not found/);
});

test('order route：POST 201、錯誤輸入 400、找不到 404', () => {
  const routes = orderRoutes();
  assert.equal(routes['POST /orders']({ body: VALID }).status, 201);
  assert.equal(routes['POST /orders']({ body: {} }).status, 400);
  assert.equal(routes['GET /orders/:id']({ params: { id: 'nope' } }).status, 404);
});
